def linear_search(items, target):
    for i in range(len(items)):
        if items[i] == target:
            return i
    return -1

print(linear_search(["佐藤", "鈴木", "高橋"], "鈴木"))

def search_steps(items, target):
    steps = 0
    for i in range(len(items)):
        steps += 1
        if items[i] == target:
            return [i, steps]
    return [-1, steps]

print(search_steps(list(range(1, 1001)), 500))

def find_all(items, target):
    result = []
    for i in range(len(items)):
        if items[i] == target:
            result.append(i)
    return result

print(find_all(["A", "B", "A", "C", "A"], "A"))

def max_index(items):
    best = 0
    for i in range(1, len(items)):
        if items[i] > items[best]:
            best = i
    return best

print(max_index([3, 9, 2, 9]))
